diff --git a/overrides/app/components/product-item/index.test.tsx b/overrides/app/components/product-item/index.test.tsx
index 5a590907..f1b82d9d 100644
--- a/overrides/app/components/product-item/index.test.tsx
+++ b/overrides/app/components/product-item/index.test.tsx
@@ -22,6 +22,14 @@
  * call-args spy on `useMultiStyleConfig` (still the REAL Chakra implementation underneath,
  * `shared/ui/useMultiStyleConfig` is a bare re-export of it — confirmed by reading that file —
  * so nothing about ProductItem's actual rendering changes; only its call args are observed).
+ *
+ * SFCC-795 (plan step 3.3) extends this file with the `discountLabel` prop's own pass criteria:
+ * omitted renders no node, present renders the exact copy positioned beneath the stepper and
+ * ahead of `message` (DOM order proven the same compareDocumentPosition way as the message-vs-
+ * actions test above). The was/now promotional-price mechanism this step also covers is NOT
+ * tested in this file — it isn't ProductItem's own contract, it's item-price.tsx's (via base
+ * `display-price`) — see item-variant/index.test.tsx's own new coverage for that, including a
+ * disclosed limitation on which of item-price.tsx's two branches can actually reach it.
  */
 import React from 'react';
 import { describe, test, expect, vi, beforeEach } from 'vitest';
@@ -336,4 +344,37 @@ describe('ProductItem', () => {
     // actionsNode follows messageNode in document order — i.e. the message precedes the actions row.
     expect(messageNode.compareDocumentPosition(actionsNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
   });
+
+  // SFCC-795 (plan step 3.3) pass criterion 2, first half: discountLabel omitted (every existing
+  // caller today) renders no empty node.
+  test('discountLabel omitted: no discount label node renders', () => {
+    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);
+
+    expect(screen.queryByTestId('zimm-discount-label')).not.toBeInTheDocument();
+  });
+
+  // SFCC-795 (plan step 3.3) pass criterion 2, second half + DOM order: with a discountLabel
+  // prop, the label renders the exact copy, positioned beneath the stepper and ahead of the
+  // (also present here) message — proving both slots coexist in the documented order rather than
+  // just individually.
+  test('discountLabel present: renders the exact copy, positioned beneath the stepper and ahead of the message', () => {
+    renderWithProviders(
+      <ProductItem
+        product={MOCK_LINE_ITEM}
+        discountLabel="20% off applied"
+        message={{ variant: 'warning', text: 'Maximum purchase quantity reached for this size' }}
+      />,
+    );
+
+    const discountNode = screen.getByTestId('zimm-discount-label');
+    expect(discountNode).toHaveTextContent('20% off applied');
+
+    const stepperNode = screen.getByText('Quantity:');
+    const messageNode = screen.getByTestId('zimm-inline-message');
+
+    // discountNode follows stepperNode in document order.
+    expect(stepperNode.compareDocumentPosition(discountNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
+    // messageNode follows discountNode in document order — i.e. the discount label precedes the message.
+    expect(discountNode.compareDocumentPosition(messageNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
+  });
 });

